for kind,rows in [('Mobile App',mobile),('Website',web)]:
 for i,(name,industry,goal,features) in enumerate(rows):
  key=name.lower().replace(' & ','-').replace(' ','-'); mobileflag=kind=='Mobile App'; fs=features.split('|'); color=['#500000','#70253d','#63334b','#833b43'][i%4]
