  svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="900" viewBox="0 0 1200 900"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#f9f3f4"/><stop offset="1" stop-color="#e2c9d1"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="25" stdDeviation="24" flood-color="#500000" flood-opacity=".18"/></filter></defs><rect width="1200" height="900" fill="url(#bg)"/><circle cx="1050" cy="110" r="340" fill="white" opacity=".45"/><circle cx="130" cy="800" r="280" fill="{color}" opacity=".08"/><text x="65" y="74" font-family="Arial" font-size="15" letter-spacing="4" fill="{color}">RIZQARA / DESIGN STUDY {i+1:02}</text>'''
  if mobileflag:
   for j,(x,y) in enumerate([(270,140),(625,210)]):
    svg+=f'<g filter="url(#shadow)"><rect x="{x}" y="{y}" width="290" height="580" rx="44" fill="#281c23"/><rect x="{x+9}" y="{y+9}" width="272" height="562" rx="36" fill="#fff"/><rect x="{x+100}" y="{y+20}" width="90" height="22" rx="11" fill="#281c23"/></g><text x="{x+30}" y="{y+90}" font-family="Arial" font-size="26" font-weight="bold" fill="{color}">{html.escape(name)}</text><text x="{x+30}" y="{y+118}" font-family="Arial" font-size="12" fill="#82727b">{html.escape(fs[j])}</text><rect x="{x+24}" y="{y+145}" width="242" height="155" rx="20" fill="{color}"/>'
    for k,h in enumerate([45,65,50,94,78,112]):svg+=f'<rect x="{x+45+k*32}" y="{y+280-h}" width="19" height="{h}" rx="6" fill="white" opacity="{.3+k*.1}"/>'
    for k in range(3):svg+=f'<rect x="{x+24}" y="{y+325+k*60}" width="242" height="48" rx="12" fill="#f6eff2"/><circle cx="{x+47}" cy="{y+349+k*60}" r="10" fill="{color}" opacity=".3"/><text x="{x+67}" y="{y+353+k*60}" font-family="Arial" font-size="11" fill="#50313d">{html.escape(fs[k])}</text>'
  else:
   svg+=f'<g filter="url(#shadow)"><rect x="120" y="180" width="960" height="560" rx="22" fill="white"/></g><path d="M142 180H1058Q1080 180 1080 202V225H120V202Q120 180 142 180" fill="{color}"/><circle cx="145" cy="203" r="5" fill="white"/><circle cx="165" cy="203" r="5" fill="#d9a9ba"/><text x="170" y="280" font-family="Arial" font-size="21" font-weight="bold" fill="{color}">{html.escape(name)}</text><text x="760" y="280" font-family="Arial" font-size="12" fill="#826572">Explore    About    Contact</text><text x="170" y="377" font-family="Arial" font-size="43" font-weight="bold" fill="{color}">{html.escape(industry)}</text><text x="170" y="416" font-family="Arial" font-size="16" fill="#82727b">Considered design. Meaningful experiences.</text><rect x="170" y="450" width="158" height="43" rx="22" fill="{color}"/><text x="195" y="477" font-family="Arial" font-size="12" fill="white">Explore our world ↗</text><rect x="710" y="325" width="310" height="190" rx="90" fill="{color}"/><ellipse cx="865" cy="420" rx="95" ry="65" fill="#dab6c4"/><ellipse cx="865" cy="420" rx="55" ry="40" fill="{color}"/>'
   for k,f in enumerate(fs):svg+=f'<rect x="{170+k*290}" y="550" width="270" height="130" rx="14" fill="#f5eef1"/><text x="{190+k*290}" y="590" font-family="Arial" font-size="12" fill="{color}">0{k+1} / EXPLORE</text><text x="{190+k*290}" y="635" font-family="Arial" font-size="15" fill="{color}">{html.escape(f)}</text>'
  svg+='<text x="65" y="850" font-family="Arial" font-size="13" letter-spacing="3" fill="#805666">INDEPENDENT CONCEPT · NOT A CLIENT COMMISSION</text></svg>'
  Path(f'public/images/projects/concepts/{key}.svg').write_text(svg)
  records.append(dict(id='concept-'+key,slug='concept-'+key,title=name+' — '+industry,category=kind,status='Concept',image=f'/images/projects/concepts/{key}.svg',description=f'{goal}. An independent {kind.lower()} design concept exploring {industry.lower()}. This is a proposed experience, not a delivered client project or a live product.',tech=['React Native','TypeScript','Proposed API integration'] if mobileflag else ['React','TypeScript','Responsive CSS'],features=fs+['Concept scope: research assumptions, interface direction, and proposed user flows','Delivery status: visual concept only; development and user validation are not completed'],gallery=[]))
